item.text:
**Скин — цифровой товар, поэтому внутри Telegram Mini App его нужно продавать за Telegram Stars (`XTR`). Принимать за него 2 TON нельзя** — это прямо указано в [документации Telegram](https://core.telegram.org/bots/payments-stars#q-can-i-accept-payment-in-cryptocurrency-instead-of-telegram-stars).

Ниже пример со Stars: `100 XTR` — условная цена, не эквивалент 2 TON.

Фронтенд создаёт счёт через ваш сервер и открывает оплату:

```html
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<button id="buy">Купить премиум-скин</button>

<script>
const webapp = Telegram.WebApp;
webapp.ready();

document.querySelector("#buy").onclick = async () => {
  try {
    const response = await fetch("/api/skin/invoice", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ initData: webapp.initData }),
    });

    if (!response.ok) throw new Error("Не удалось создать счёт");

    const { url } = await response.json();
    webapp.openInvoice(url);

    // Право на скин фронтенд получает из серверного инвентаря.
    // Callback openInvoice сам по себе не выдаёт покупку.
  } catch (error) {
    webapp.showAlert(error.message);
  }
};
</script>
```

Бэкенд: Node.js 20+, Express 5. `db` ниже — адаптер вашей постоянной БД; его обязательный контракт описан после кода.

```js
import express from "express";
import {
  createHmac,
  timingSafeEqual,
  randomUUID,
} from "node:crypto";

const TOKEN = process.env.BOT_TOKEN;
const SECRET = process.env.TG_WEBHOOK_SECRET;
const SKU = "premium_skin";
const PRICE = 100; // Целое количество Stars, задаётся сервером.

if (!TOKEN || !SECRET) throw new Error("Missing Telegram credentials");

async function telegram(method, params) {
  const response = await fetch(
    `https://api.telegram.org/bot${TOKEN}/${method}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(params),
      signal: AbortSignal.timeout(5000),
    },
  );

  const result = await response.json();
  if (!response.ok || !result.ok) {
    throw new Error(result.description || "Telegram API error");
  }
  return result.result;
}

// Проверяем исходный initData, а не initDataUnsafe.
function authenticatedUser(raw) {
  if (typeof raw !== "string") throw new Error("Missing initData");

  const params = new URLSearchParams(raw);
  const keys = [...params.keys()];
  if (new Set(keys).size !== keys.length) throw new Error("Duplicate fields");

  const hash = params.get("hash") ?? "";
  if (!/^[a-f0-9]{64}$/i.test(hash)) throw new Error("Invalid hash");

  params.delete("hash");
  params.sort();
  const data = [...params].map(([k, v]) => `${k}=${v}`).join("\n");

  const key = createHmac("sha256", "WebAppData").update(TOKEN).digest();
  const expected = createHmac("sha256", key).update(data).digest();

  if (!timingSafeEqual(expected, Buffer.from(hash, "hex"))) {
    throw new Error("Invalid signature");
  }

  const issued = Number(params.get("auth_date"));
  const now = Math.floor(Date.now() / 1000);
  if (!Number.isInteger(issued) || issued > now + 30 || now - issued > 3600) {
    throw new Error("Expired initData");
  }

  const user = JSON.parse(params.get("user") ?? "null");
  if (!Number.isSafeInteger(user?.id)) throw new Error("Missing user");

  return String(user.id);
}

function matches(order, payerId, payment) {
  return Boolean(
    order &&
    order.userId === String(payerId) &&
    order.sku === SKU &&
    order.currency === payment.currency &&
    order.amount === payment.total_amount
  );
}

export function installPayments(app, db) {
  app.use(express.json());

  app.post("/api/skin/invoice", async (req, res) => {
    let userId;
    try {
      userId = authenticatedUser(req.body?.initData);
    } catch {
      return res.sendStatus(401);
    }

    const order = {
      id: randomUUID(),
      userId,
      sku: SKU,
      currency: "XTR",
      amount: PRICE,
      paid: false,
    };
    await db.createOrder(order);

    const url = await telegram("createInvoiceLink", {
      title: "Премиум-скин",
      description: "Премиум-скин для игры",
      payload: order.id,
      provider_token: "",
      currency: order.currency,
      prices: [{ label: "Скин", amount: order.amount }],
    });

    res.json({ url });
  });

  app.post("/telegram/webhook", async (req, res) => {
    if (req.get("X-Telegram-Bot-Api-Secret-Token") !== SECRET) {
      return res.sendStatus(403);
    }

    try {
      const query = req.body.pre_checkout_query;
      if (query) {
        const order = await db.getOrder(query.invoice_payload);
        const ok = matches(order, query.from.id, query) && !order.paid;

        // Telegram должен получить ответ в течение 10 секунд.
        await telegram("answerPreCheckoutQuery", {
          pre_checkout_query_id: query.id,
          ok,
          ...(ok ? {} : { error_message: "Заказ недоступен для оплаты" }),
        });
      }

      const message = req.body.message;
      const payment = message?.successful_payment;

      if (payment) {
        const order = await db.getOrder(payment.invoice_payload);
        if (!matches(order, message.from.id, payment)) {
          throw new Error("Payment does not match order");
        }

        // Завершается только после COMMIT платежа и выдачи скина.
        await db.payAndGrantOnce({
          orderId: order.id,
          userId: String(message.from.id),
          currency: payment.currency,
          amount: payment.total_amount,
          chargeId: payment.telegram_payment_charge_id,
        });
      }

      res.sendStatus(200);
    } catch (error) {
      console.error(error);
      res.sendStatus(500); // Telegram повторит доставку webhook.
    }
  });
}

// Выполнить при настройке, когда HTTPS endpoint уже доступен:
export async function registerWebhook(publicOrigin) {
  await telegram("setWebhook", {
    url: `${publicOrigin}/telegram/webhook`,
    secret_token: SECRET,
    allowed_updates: ["message", "pre_checkout_query"],
  });
}
```

`db.payAndGrantOnce` нужно реализовать **одной транзакцией**: заблокировать заказ, повторно проверить пользователя/валюту/сумму, сохранить платёж, отметить заказ оплаченным и добавить скин в инвентарь. На `telegram_payment_charge_id` нужен `UNIQUE`. Повтор того же платежа должен успешно завершаться без повторной выдачи; другой платёж за уже оплаченный заказ требует сверки и возврата, его нельзя молча игнорировать.

Выдача происходит только после серверного `successful_payment`. Сохранённый `chargeId` также нужен для `refundStarPayment`. Для платёжной поддержки Telegram требует обработку `/paysupport`.

Документация: [платежи Stars](https://core.telegram.org/bots/payments-stars), [проверка initData](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app).
